/*
// Definition for a Node.
class Node {
    int val;
    Node next;
    Node random;

    public Node(int val) {
        this.val = val;
        this.next = null;
        this.random = null;
    }
}
*/

class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) {
            return head;
        }

        var oldToNew = new HashMap<Node, Node>();
        var cur = head;
        var dummy = new Node(0);
        var newHead = dummy;
        while (cur != null) {
            newHead.next = new Node(cur.val);
            oldToNew.put(cur, newHead.next);
            cur = cur.next;
            newHead = newHead.next;
        }

        cur = head;
        while (cur != null) {
            oldToNew.get(cur).random = oldToNew.get(cur.random);
            cur = cur.next;
        }

        return dummy.next;
    }
}

